请对以下 case 进行三维加权评分。

=== case_id ===
Case-05-agenda-019

=== 用户原始指令 (query.txt) ===
帮我做一个行程管理卡片，不用图片，纯色块拼。背景用那种模拟深夜星空的渐变色，分左右两块区域，左边是信息区，用分隔线划开，上面显示日历接下来的议程和地点，如果遇到迟到风险就显示红色感叹号；右边是动作区，有个跳转按钮能直接打开闹钟应用去设定叫醒时间，顺便在卡片顶部标个今日步数“已行走3500步”。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做一个行程管理卡片，不用图片，纯色块拼。背景用那种模拟深夜星空的渐变色，分左右两块区域，左边是信息区，用分隔线划开，上面显示日历接下来的议程和地点，如果遇到迟到风险就显示红色感叹号；右边是动作区，有个跳转按钮能直接打开闹钟应用去设定叫醒时间，顺便在卡片顶部标个今日步数“已行走3500步”。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日程项唯一标识符，可用于打开日程详情。",
              "sampleValue": "calendar-event-001"
            },
            "title": {
              "type": "string",
              "description": "接下来的日程标题。",
              "sampleValue": "产品评审"
            },
            "eventLocation": {
              "type": "string",
              "description": "日程发生地点。",
              "sampleValue": "A座 18F"
            },
            "dtStart": {
              "type": "string",
              "description": "日程开始时间，当天日程通常为 HH:MM。",
              "sampleValue": "09:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "日程结束时间，当天日程通常为 HH:MM。",
              "sampleValue": "10:30"
            }
          }
        ]
      }
    },
    "state": {
      "stepText": {
        "type": "string",
        "description": "今日步数短文本。",
        "sampleValue": "已行走3500步"
      },
      "lateRiskText": {
        "type": "string",
        "description": "迟到风险提示符号，有风险时显示红色感叹号。",
        "sampleValue": "!"
      }
    }
  },
  "assetCandidates": []
}

